from collections import defaultdict

def average_across_dicts_zero_fill(dicts_list):
    n = len(dicts_list)
    if n == 0:
        return {}
    totals = defaultdict(int)
    for d in dicts_list:
        for k, v in d.items():
            totals[k] += v
    return {k: round(total / n, 2) for k, total in totals.items()}
```
