def is_valid_self_closing_mix(s):
    def valid_word(w):
        return bool(w) and w.isalpha() and w.islower()

    stack = []
    i, n = 0, len(s)
    while i < n:
        if s[i] != '<':
            return False
        end = s.find('>', i)
        if end == -1:
            return False
        token, i = s[i + 1:end], end + 1
        if token.startswith('/'):
            word = token[1:]
            if not stack or stack.pop() != word:
                return False
        elif token.endswith('/'):
            if not valid_word(token[:-1]):
                return False
        else:
            if not valid_word(token):
                return False
            stack.append(token)
    return not stack
