def average_across_dicts_zero_fill(dicts_list):
    n = len(dicts_list)
    if n == 0:
        return {}
    keys = set()
    for d in dicts_list:
        keys |= set(d.keys())
    result = {}
    for k in keys:
        total = 0
        for d in dicts_list:
            total += d.get(k, 0)
        result[k] = round(total / n, 2)
    return result
